SELECT id,
       device_id,
       device_code,
       event_type,
       payload::text AS payload,
       run_id,
       created_at
  FROM device_event
 WHERE tenant_id = #{tenantId}
   AND id > #{afterId}

   AND device_code = #{deviceCode}


   AND event_type = #{eventType}

 ORDER BY id
 LIMIT #{limit}

SELECT COALESCE(MAX(id), 0)
  FROM device_event
 WHERE tenant_id = #{tenantId}

mapper.update:
UPDATE device_event
   SET dispatched_at = now(),
       attempts = attempts + 1
 WHERE tenant_id = #{tenantId}
   AND id = #{id}
   AND dispatched_at IS NULL
